CREATE PROCEDURE sp_inscribir_alumno_comision_tx (
  IN p_id_alumno INT,
  IN p_id_comision INT
)
BEGIN
  DECLARE v_cupo INT;
  DECLARE v_inscriptos INT;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    RESIGNAL;
  END;

  START TRANSACTION;

  SELECT cupo INTO v_cupo FROM comisiones WHERE id_comision = p_id_comision FOR UPDATE;
  IF v_cupo IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'La comision no existe';
  END IF;

  IF EXISTS (SELECT 1 FROM inscripcion_alumno_comision
             WHERE id_alumno = p_id_alumno AND id_comision = p_id_comision) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'El alumno ya esta inscripto en la comision';
  END IF;

  SELECT COUNT(*) INTO v_inscriptos
  FROM inscripcion_alumno_comision
  WHERE id_comision = p_id_comision;
  IF v_inscriptos >= v_cupo THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'No hay cupo disponible';
  END IF;

  INSERT INTO inscripcion_alumno_comision (id_alumno, id_comision, fecha_inscripcion, estado)
  VALUES (p_id_alumno, p_id_comision, CURDATE(), 'Cursa');

  COMMIT;
END $$

DELIMITER ;

