CREATE PROCEDURE sp_registrar_nota_tx (
  IN p_id_alumno INT,
  IN p_id_examen INT,
  IN p_nota DECIMAL(4,2)
)
BEGIN
  DECLARE v_id_comision INT;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    RESIGNAL;
  END;

  START TRANSACTION;

  IF p_nota < 0 OR p_nota > 10 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'La nota debe estar entre 0 y 10';
  END IF;

  SELECT id_comision INTO v_id_comision FROM examenes WHERE id_examen = p_id_examen;
  IF v_id_comision IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'El examen no existe';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM inscripcion_alumno_comision
                 WHERE id_alumno = p_id_alumno AND id_comision = v_id_comision) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'El alumno no esta inscripto en la comision del examen';
  END IF;

  IF EXISTS (SELECT 1 FROM notas WHERE id_alumno = p_id_alumno AND id_examen = p_id_examen) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'El alumno ya tiene nota en este examen';
  END IF;

  INSERT INTO notas (id_examen, id_alumno, nota, aprobado)
  VALUES (p_id_examen, p_id_alumno, p_nota, p_nota >= 4);

  UPDATE inscripcion_alumno_comision
  SET estado = IF(p_nota >= 4, 'Aprobada', 'Regular')
  WHERE id_alumno = p_id_alumno AND id_comision = v_id_comision;

  COMMIT;
END $$

