CREATE TABLE auditoria_bajas_comision (
  id_auditoria    INT AUTO_INCREMENT PRIMARY KEY,
  id_inscripcion  INT,
  id_alumno       INT,
  id_comision     INT,
  estado_anterior VARCHAR(20),
  motivo          VARCHAR(255),
  fecha_baja      DATETIME
);

DELIMITER $$

CREATE PROCEDURE sp_dar_baja_inscripcion_tx (
  IN p_id_inscripcion INT,
  IN p_motivo VARCHAR(255)
)
BEGIN
  DECLARE v_id_alumno INT;
  DECLARE v_id_comision INT;
  DECLARE v_estado VARCHAR(20);
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    RESIGNAL;
  END;

  START TRANSACTION;

  SELECT id_alumno, id_comision, estado
    INTO v_id_alumno, v_id_comision, v_estado
  FROM inscripcion_alumno_comision
  WHERE id_inscripcion = p_id_inscripcion
  FOR UPDATE;

  IF v_id_alumno IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'La inscripcion no existe';
  END IF;
  IF v_estado = 'Baja' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'La inscripcion ya esta dada de baja';
  END IF;

  INSERT INTO auditoria_bajas_comision (id_inscripcion, id_alumno, id_comision, estado_anterior, motivo, fecha_baja)
  VALUES (p_id_inscripcion, v_id_alumno, v_id_comision, v_estado, p_motivo, NOW());

  UPDATE inscripcion_alumno_comision
  SET estado = 'Baja'
  WHERE id_inscripcion = p_id_inscripcion;

  COMMIT;
END $$

DELIMITER ;

