CREATE PROCEDURE sp_crear_comision_tx (
  IN p_id_asignatura INT,
  IN p_id_docente INT,
  IN p_id_aula INT,
  IN p_anio INT,
  IN p_cuatrimestre INT,
  IN p_cupo INT,
  IN p_tipo VARCHAR(20)
)
BEGIN
  DECLARE v_capacidad INT;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    RESIGNAL;
  END;

  START TRANSACTION;

  IF p_cupo IS NULL OR p_cupo <= 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'El cupo debe ser mayor que cero';
  END IF;

  SELECT capacidad INTO v_capacidad FROM aulas WHERE id_aula = p_id_aula;
  IF v_capacidad IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'El aula no existe';
  END IF;
  IF v_capacidad < p_cupo THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'La capacidad del aula no alcanza para el cupo';
  END IF;

  INSERT INTO comisiones (id_asignatura, id_docente, id_aula, anio, cuatrimestre, cupo, tipo)
  VALUES (p_id_asignatura, p_id_docente, p_id_aula, p_anio, p_cuatrimestre, p_cupo, p_tipo);

  COMMIT;
END $$

