CREATE TABLE auditoria_salarios_docentes (
  id_auditoria     INT AUTO_INCREMENT PRIMARY KEY,
  id_docente       INT,
  salario_anterior DECIMAL(10,2),
  salario_nuevo    DECIMAL(10,2),
  fecha_cambio     DATETIME
);

DELIMITER $$

CREATE PROCEDURE sp_actualizar_salario_docente_tx (
  IN p_id_docente INT,
  IN p_salario_nuevo DECIMAL(10,2)
)
BEGIN
  DECLARE v_salario_anterior DECIMAL(10,2);
  DECLARE v_existe INT;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    RESIGNAL;
  END;

  START TRANSACTION;

  IF p_salario_nuevo < 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'El salario no puede ser negativo';
  END IF;

  SELECT COUNT(*), MAX(salario_base) INTO v_existe, v_salario_anterior
  FROM docentes WHERE id_docente = p_id_docente;
  IF v_existe = 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'El docente no existe';
  END IF;

  INSERT INTO auditoria_salarios_docentes (id_docente, salario_anterior, salario_nuevo, fecha_cambio)
  VALUES (p_id_docente, v_salario_anterior, p_salario_nuevo, NOW());

  UPDATE docentes SET salario_base = p_salario_nuevo WHERE id_docente = p_id_docente;

  COMMIT;
END $$

DELIMITER ;

